Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
fbdev: au1200fb: Fix a memory leak in au1200fb_drv_probe()

In au1200fb_drv_probe(), when platform_get_irq fails(), it directly
returns from the function with an error code, which causes a memory
leak.

Replace it with a goto label to ensure proper cleanup.

Fixes: 4e88761f5f8c ("fbdev: au1200fb: Fix missing IRQ check in au1200fb_drv_probe")
Signed-off-by: Felix Gu <ustc.gu@gmail.com>
Signed-off-by: Helge Deller <deller@gmx.de>

Here is the root cause:
The bug is due to improper error handling in `au1200fb_drv_probe()`. When `platform_get_irq()` fails (returns a negative error code), the original code directly returned that error code without performing any cleanup via the `failed` label. This skipped the release of previously allocated resources (e.g., framebuffer memory), leading to a memory leak. The patch fixes this by assigning the error code to `ret` and jumping to the `failed` label to ensure proper resource deallocation.

Here is the patch:
 /* AU1200 LCD controller device driver */
 static int au1200fb_drv_probe(struct platform_device *dev)
 {
 	struct au1200fb_device *fbdev;
 	struct au1200fb_platdata *pd;
 	struct fb_info *fbi = NULL;
 	int bpp, plane, ret, irq;

 	print_info("" DRIVER_DESC "");

 	pd = dev->dev.platform_data;
 	if (!pd)
 		return -ENODEV;

 	/* Setup driver with options */
 	if (au1200fb_setup(pd))
 		return -ENODEV;

 	/* Point to the panel selected */
 	panel = &known_lcd_panels[panel_index];
 	win = &windows[window_index];

 	printk(DRIVER_NAME ": Panel %d %s\n", panel_index, panel->name);
 	printk(DRIVER_NAME ": Win %d %s\n", window_index, win->name);

 	for (plane = 0; plane < device_count; ++plane) {
 		bpp = winbpp(win->w[plane].mode_winctrl1);
 		if (win->w[plane].xres == 0)
 			win->w[plane].xres = panel->Xres;
 		if (win->w[plane].yres == 0)
 			win->w[plane].yres = panel->Yres;

 		fbi = framebuffer_alloc(sizeof(struct au1200fb_device),
 					&dev->dev);
 		if (!fbi) {
 			ret = -ENOMEM;
 			goto failed;
 		}

 		_au1200fb_infos[plane] = fbi;
 		fbdev = fbi->par;
 		fbdev->fb_info = fbi;
 		fbdev->pd = pd;
 		fbdev->dev = &dev->dev;

 		fbdev->plane = plane;

 		/* Allocate the framebuffer to the maximum screen size */
 		fbdev->fb_len = (win->w[plane].xres * win->w[plane].yres * bpp) / 8;

 		fbdev->fb_mem = dmam_alloc_attrs(&dev->dev,
 				PAGE_ALIGN(fbdev->fb_len),
 				&fbdev->fb_phys, GFP_KERNEL, 0);
 		if (!fbdev->fb_mem) {
 			print_err("fail to allocate framebuffer (size: %dK))",
 				  fbdev->fb_len / 1024);
 			ret = -ENOMEM;
 			goto failed;
 		}

 		print_dbg("Framebuffer memory map at %p", fbdev->fb_mem);
 		print_dbg("phys=0x%08x, size=%dK", fbdev->fb_phys, fbdev->fb_len / 1024);

 		/* Init FB data */
 		ret = au1200fb_init_fbinfo(fbdev);
 		if (ret < 0)
 			goto failed;

 		/* Register new framebuffer */
 		ret = register_framebuffer(fbi);
 		if (ret < 0) {
 			print_err("cannot register new framebuffer");
 			goto failed;
 		}

 		au1200fb_fb_set_par(fbi);
 	}

 	/* Now hook interrupt too */
 	irq = platform_get_irq(dev, 0);
-	if (irq < 0)
-		return irq;
+	if (irq < 0) {
+		ret = irq;
+		goto failed;
+	}

 	ret = request_irq(irq, au1200fb_handle_irq,
 			  IRQF_SHARED, "lcd", (void *)dev);
 	if (ret) {
 		print_err("fail to request interrupt line %d (err: %d)",
 			  irq, ret);
 		goto failed;
 	}

 	platform_set_drvdata(dev, pd);

 	/* Kickstart the panel */
 	au1200_setpanel(panel, pd);

 	return 0;

 failed:
 	for (plane = 0; plane < device_count; ++plane) {
 		fbi = _au1200fb_infos[plane];
 		if (!fbi)
 			break;

 		/* Clean up all probe data */
 		unregister_framebuffer(fbi);
 		if (fbi->cmap.len != 0)
 			fb_dealloc_cmap(&fbi->cmap);
 		kfree(fbi->pseudo_palette);

 		framebuffer_release(fbi);
 		_au1200fb_infos[plane] = NULL;
 	}
 	return ret;
 }



